/**
 * Principia Metaphysica - path context (classic script, first in <head>).
 *
 * Holds the selected theory path (?path= -> sessionStorage "pm.path" -> main),
 * overlays fetch() of AutoGenerated/<file>.json with that path's RFC 6902 patch
 * (refused on a sha256 mismatch), shows the bar off main and the "Main path" chip
 * on main, and keeps ?path= on internal links.  Contract: docs/plan/paths/contracts.md
 * section 6 (D-021).  Exposes window.PMPath for the Paths page.
 */
(function (root) {
  'use strict';

  var STORE_KEY = 'pm.path';
  var ID_RE = /^[A-Za-z0-9_]+(--[A-Za-z0-9_]+)?$/;
  var MAIN = 'main';
  var NOTICE = 'results unavailable for this file: showing main';

  // ---------- pure core (also used by tests/js/path_context.test.mjs) ----------

  function unescapePointer(token) {
    return token.replace(/~1/g, '/').replace(/~0/g, '~');
  }

  function parsePointer(ptr) {
    if (ptr === '') return [];
    if (ptr.charAt(0) !== '/') throw new Error('bad pointer: ' + ptr);
    return ptr.slice(1).split('/').map(unescapePointer);
  }

  function walk(doc, tokens) {
    var cur = doc;
    for (var i = 0; i < tokens.length; i++) {
      if (cur === null || typeof cur !== 'object' || !(tokens[i] in cur)) {
        throw new Error('missing path segment: ' + tokens[i]);
      }
      cur = cur[tokens[i]];
    }
    return cur;
  }

  function arrayIndex(tok, len, allowEnd) {
    if (allowEnd && tok === '-') return len;
    if (!/^(0|[1-9][0-9]*)$/.test(tok)) throw new Error('bad array index: ' + tok);
    var n = Number(tok);
    if (n > len || (!allowEnd && n === len)) throw new Error('index out of range: ' + tok);
    return n;
  }

  function applyOne(doc, op) {
    var tokens = parsePointer(op.path);
    if (tokens.length === 0) {
      if (op.op === 'remove') throw new Error('cannot remove the document root');
      return JSON.parse(JSON.stringify(op.value));
    }
    var last = tokens[tokens.length - 1];
    var parent = walk(doc, tokens.slice(0, -1));
    if (Array.isArray(parent)) {
      var idx = arrayIndex(last, parent.length, op.op === 'add');
      if (op.op === 'add') parent.splice(idx, 0, op.value);
      else if (op.op === 'remove') parent.splice(idx, 1);
      else parent[idx] = op.value;
    } else if (parent !== null && typeof parent === 'object') {
      if (op.op !== 'add' && !(last in parent)) throw new Error('missing key: ' + last);
      if (op.op === 'remove') delete parent[last];
      else parent[last] = op.value;
    } else {
      throw new Error('parent is not a container');
    }
    return doc;
  }

  /** Apply add/remove/replace ops to a deep copy of doc; throws on any bad op. */
  function applyPatch(doc, ops) {
    var out = JSON.parse(JSON.stringify(doc));
    (ops || []).forEach(function (op) {
      if (op.op !== 'add' && op.op !== 'remove' && op.op !== 'replace') {
        throw new Error('unsupported op: ' + op.op);
      }
      out = applyOne(out, op);
    });
    return out;
  }

  /** Selection precedence: a known ?path= wins, then a known stored id, then main. */
  function chooseId(search, stored, known) {
    var q = null;
    try { q = new URLSearchParams(search || '').get('path'); } catch (e) { q = null; }
    var ok = function (id) {
      return !!id && ID_RE.test(id) && (id === MAIN || !known || known.indexOf(id) >= 0);
    };
    if (ok(q)) return q;
    if (ok(stored)) return stored;
    return MAIN;
  }

  /**
   * Check bytes against the patch entry and apply it.
   * sha256 is async (bytes -> hex or null).  Returns {ok, text} or {ok:false, reason}.
   */
  function resolveOverlay(bytes, entry, sha256, decode) {
    return Promise.resolve(sha256(bytes)).then(function (hex) {
      if (!hex || hex !== entry.base_sha256) return { ok: false, reason: 'sha256 mismatch' };
      var doc = JSON.parse(decode(bytes));
      return { ok: true, text: JSON.stringify(applyPatch(doc, entry.ops)) };
    }).catch(function (err) {
      return { ok: false, reason: String(err && err.message || err) };
    });
  }

  var core = {
    applyPatch: applyPatch, unescapePointer: unescapePointer, chooseId: chooseId,
    resolveOverlay: resolveOverlay, MAIN: MAIN, NOTICE: NOTICE
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = core;
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  // ---------- browser part ----------

  var scriptEl = document.currentScript;
  var scriptUrl = new URL(scriptEl && scriptEl.src ? scriptEl.src : 'js/pm-path-context.js', location.href);
  var autoBase = new URL('../AutoGenerated/', scriptUrl);
  var pagesBase = new URL('../Pages/', scriptUrl);
  var origFetch = window.fetch ? window.fetch.bind(window) : null;
  var indexPromise = null;
  var patchPromises = {};
  var current = MAIN;
  var indexData = null;
  var notices = [];

  function storeGet() {
    try { return sessionStorage.getItem(STORE_KEY); } catch (e) { return null; }
  }
  function storeSet(id) {
    try {
      if (id && id !== MAIN) sessionStorage.setItem(STORE_KEY, id);
      else sessionStorage.removeItem(STORE_KEY);
    } catch (e) { /* storage unavailable: selection lasts for this page only */ }
  }

  function loadJson(url) {
    return origFetch(url).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status + ' for ' + url);
      return r.json();
    });
  }

  function loadIndex() {
    if (!indexPromise) {
      indexPromise = origFetch ? loadJson(new URL('paths/index.json', autoBase).href)
        .then(function (d) { indexData = d; return d; })
        .catch(function () { indexData = null; return null; }) : Promise.resolve(null);
    }
    return indexPromise;
  }

  function loadPatch(id) {
    if (!patchPromises[id]) {
      patchPromises[id] = loadJson(new URL('paths/' + id + '/patch.json', autoBase).href)
        .catch(function () { return null; });
    }
    return patchPromises[id];
  }

  function entryFor(id) {
    var list = (indexData && indexData.paths) || [];
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }

  /** The file key under AutoGenerated/ for a fetch input, or null if not overlaid. */
  function overlayKey(input) {
    var raw = typeof input === 'string' ? input : (input && input.url) || String(input);
    var u;
    try { u = new URL(raw, location.href); } catch (e) { return null; }
    if (u.origin !== autoBase.origin || u.pathname.indexOf(autoBase.pathname) !== 0) return null;
    var key = decodeURIComponent(u.pathname.slice(autoBase.pathname.length));
    if (!/\.json$/.test(key) || key.indexOf('paths/') === 0) return null;
    return key;
  }

  function sha256Hex(buf) {
    if (!root.crypto || !root.crypto.subtle) return Promise.resolve(null);
    return root.crypto.subtle.digest('SHA-256', buf).then(function (d) {
      return Array.prototype.map.call(new Uint8Array(d), function (b) {
        return ('0' + b.toString(16)).slice(-2);
      }).join('');
    }).catch(function () { return null; });
  }

  function noteUnavailable(key) {
    if (notices.indexOf(key) < 0) notices.push(key);
    renderBar();
  }

  function overlay(input, init, key) {
    var id = current;
    var baseReq = origFetch(input, init);
    return Promise.all([loadIndex(), loadPatch(id), baseReq]).then(function (r) {
      var patch = r[1], base = r[2];
      var entry = patch && patch.files && patch.files[key];
      if (!entry || !base.ok) return base;
      return base.clone().arrayBuffer().then(function (bytes) {
        return resolveOverlay(bytes, entry, sha256Hex, function (b) {
          return new TextDecoder('utf-8').decode(b);
        });
      }).then(function (res) {
        if (!res.ok) { noteUnavailable(key); return base; }
        return new Response(res.text, { status: 200, headers: { 'Content-Type': 'application/json' } });
      });
    });
  }

  function wrapFetch() {
    if (!origFetch) return;
    window.fetch = function (input, init) {
      var method = (init && init.method) || (input && input.method) || 'GET';
      var key = current !== MAIN && method.toUpperCase() === 'GET' ? overlayKey(input) : null;
      return key ? overlay(input, init, key) : origFetch(input, init);
    };
  }

  // ---------- selection ----------

  function urlWithPath(id) {
    var u = new URL(location.href);
    if (id && id !== MAIN) u.searchParams.set('path', id);
    else u.searchParams.delete('path');
    return u.href;
  }

  function select(id) {
    if (!ID_RE.test(id || '')) return;
    storeSet(id);
    location.assign(urlWithPath(id));
  }

  function returnToMain() {
    storeSet(MAIN);
    location.assign(urlWithPath(MAIN));
  }

  // ---------- bar and chip ----------

  function mk(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function styleBox(e, css) { e.style.cssText = css; return e; }

  function buildBar(entry) {
    var bar = styleBox(mk('div', 'pm-path-bar'), 'position:sticky;top:0;z-index:10000;display:flex;' +
      'flex-wrap:wrap;gap:.6rem;align-items:center;padding:.5rem 1rem;background:#2a2410;' +
      'color:#f8f9fa;border-bottom:2px solid #ffd93d;font:14px/1.4 system-ui,sans-serif;');
    bar.setAttribute('role', 'status');
    var label = entry ? entry.label : current;
    var status = entry ? entry.status : 'unknown';
    var msg = mk('span');
    msg.appendChild(document.createTextNode('Viewing path '));
    msg.appendChild(mk('strong', '', label));
    msg.appendChild(document.createTextNode(' (' + status + '). These are this path’s results, ' +
      'not the theory’s predictions.'));
    bar.appendChild(msg);
    var why = mk('a', 'pm-path-why', 'Why');
    why.href = new URL('paths.html#' + current, pagesBase).href;
    var back = mk('button', 'pm-path-return', 'Return to main path');
    back.type = 'button';
    back.addEventListener('click', returnToMain);
    styleBox(back, 'cursor:pointer;background:#ffd93d;color:#1a1a1a;border:0;border-radius:4px;padding:.25rem .7rem;font:inherit;');
    why.style.cssText = 'color:#ffd93d;';
    bar.appendChild(why);
    bar.appendChild(back);
    bar.appendChild(styleBox(mk('span', 'pm-path-notice'), 'flex-basis:100%;color:#ffb554;'));
    return bar;
  }

  function buildChip() {
    var chip = mk('a', 'pm-path-chip', 'Main path');
    chip.href = new URL('paths.html', pagesBase).href;
    chip.title = 'This is the main path (the D-015 active path). See all paths.';
    styleBox(chip, 'position:fixed;right:.75rem;bottom:.75rem;z-index:10000;padding:.2rem .7rem;' +
      'border-radius:999px;background:#ffd93d;color:#1a1a1a;font:600 12px system-ui,sans-serif;' +
      'text-decoration:none;box-shadow:0 1px 4px rgba(0,0,0,.4);');
    return chip;
  }

  function renderBar() {
    var bar = document.querySelector('.pm-path-bar');
    if (!bar) return;
    var n = bar.querySelector('.pm-path-notice');
    n.textContent = notices.length ? NOTICE + ' (' + notices.join(', ') + ')' : '';
  }

  function mountUi() {
    if (!document.body || document.querySelector('.pm-path-bar, .pm-path-chip')) return;
    if (current === MAIN) {
      document.body.appendChild(buildChip());
    } else {
      document.body.insertBefore(buildBar(entryFor(current)), document.body.firstChild);
      renderBar();
    }
  }

  function onReady(fn) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn);
    else fn();
  }

  // ---------- links ----------

  function onLinkClick(ev) {
    if (current === MAIN || ev.defaultPrevented) return;
    var a = ev.target && ev.target.closest ? ev.target.closest('a[href]') : null;
    if (!a || a.target === '_blank' || a.hasAttribute('download')) return;
    var raw = a.getAttribute('href');
    if (!raw || raw.charAt(0) === '#' || /^(mailto|tel|javascript):/i.test(raw)) return;
    var u;
    try { u = new URL(a.href); } catch (e) { return; }
    if (u.origin !== location.origin || u.searchParams.has('path')) return;
    if (!/(\.html?|\/)$/.test(u.pathname)) return;
    u.searchParams.set('path', current);
    a.href = u.href;
  }

  // ---------- start ----------

  function start() {
    var stored = storeGet();
    var q = new URLSearchParams(location.search).get('path');
    current = chooseId(location.search, stored, null);
    wrapFetch();
    var ready = new Promise(function (res) { onReady(res); });
    Promise.all([loadIndex(), ready]).then(function () {
      var known = ((indexData && indexData.paths) || []).map(function (p) { return p.id; });
      if (current !== MAIN && (!indexData || known.indexOf(current) < 0)) {
        current = MAIN;
        storeSet(MAIN);
      } else if (q === current) {
        storeSet(current);
      }
      mountUi();
    });
    document.addEventListener('click', onLinkClick, true);
  }

  window.PMPath = {
    current: function () { return current; },
    select: select,
    returnToMain: returnToMain,
    applyPatch: applyPatch,
    index: function () { return loadIndex(); }
  };
  start();
})(typeof window !== 'undefined' ? window : globalThis);
